-- Caso completo confirmado por el propietario: tarjeta100, condonar400 y revertir400.
-- Sólo documentación; nunca crear ni cambiar registros financieros desde esta migración.
INSERT INTO guia_proceso(slug,titulo,categoria,resumen,requisitos,ejemplo,version_contenido,revisada_el,estado)
VALUES ('condonacion-abono-previo-100-400',$texto$Condonar y reactivar $400 conservando un pago previo de $100$texto$,'Cobranza',$texto$Registrar un pago parcial con tarjeta, condonar el saldo restante y cancelar el convenio sin perder el abono ni su comprobante y sin mover nuevamente el banco.$texto$,$texto$Adeudo de prueba de $500.00, sin abonos ni ajustes activos, con tutor responsable y acceso familiar. Administrador persistido con permisos para pagos, convenios, adeudos y consulta de cuentas; cuenta bancaria activa del plantel y moneda correspondientes. Usar registros controlados: si ya completaste el caso, consultar el resultado sin repetir pagos o convenios. No usar un convenio real ni el convenio de dos hijos ya liquidado.$texto$,$texto$Banco inicial B. Cargo $500.00 → pago con tarjeta $100.00 validado: banco B + $100.00 y deuda $400.00 → condonación de $400.00: deuda $0.00, banco B + $100.00 → cancelar convenio: deuda $400.00, abono $100.00 y comprobante conservados, banco B + $100.00. Confirmado por el propietario el 08/10/2026.$texto$,1,DATE '2026-10-08','CONFIRMADA');
INSERT INTO guia_proceso_permiso(guia_id,permiso_id)
SELECT g.id,p.id FROM guia_proceso g JOIN permiso p ON p.codigo=ANY(ARRAY['CONVENIO_PAGO_ADMINISTRAR','CARGO_ADMINISTRAR','PAGO_REGISTRAR','PAGO_VALIDAR','CUENTA_FINANCIERA_LEER']) WHERE g.slug='condonacion-abono-previo-100-400';
INSERT INTO guia_proceso_paso(guia_id,numero,titulo,perfil,modulo,instrucciones,ejemplo,resultado,precaucion,ruta)
SELECT g.id,v.numero,v.titulo,v.perfil,v.modulo,v.instrucciones,v.ejemplo,v.resultado,v.precaucion,v.ruta FROM guia_proceso g JOIN (VALUES
('condonacion-abono-previo-100-400',1,$texto$Identificar el adeudo original de $500$texto$,$texto$Administración$texto$,$texto$Adeudos de alumnos$texto$,$texto$1. Desde el menú lateral entra a Operación escolar → Cobranza escolar → Adeudos de alumnos. Busca la matrícula del alumno, selecciona Con saldo pendiente y pulsa Aplicar filtros. 2. En el cargo de prueba de $500.00 pulsa Ver → Resumen; confirma total $500.00, pagado acumulado $0.00 y saldo por pagar $500.00. Anota número del cargo, alumno, concepto y tutor responsable. 3. Si no tienes ese original, entra a Administración → Seguridad y soporte → Guía de procesos, busca Cancelar una condonación total: recuperar el adeudo de $500 y sigue su preparación y reactivación; después vuelve al módulo de Adeudos de alumnos y consulta el original. No crees una copia si ya existe. 4. Si ya completaste este caso y ves $100.00 pagados y $400.00 pendientes, omite nuevas capturas y consulta sus pagos y convenios; no repitas el abono de prueba.$texto$,$texto$Original $500.00 sin abonos al iniciar.$texto$,$texto$Cargo y responsable identificados.$texto$,$texto$No usar Registrar pago del detalle para este ejemplo: el pago rápido protege el cargo completo y no ofrece pago parcial. Usar Nuevo registro de Pagos recibidos.$texto$,$texto$/admin/catalogos/cargos$texto$),
('condonacion-abono-previo-100-400',2,$texto$Anotar el saldo del banco antes del pago$texto$,$texto$Administración$texto$,$texto$Cuentas financieras$texto$,$texto$1. Desde el menú lateral entra a Administración → Finanzas → Cuentas financieras. Busca la cuenta bancaria de prueba y pulsa Aplicar filtros. 2. Anota Saldo actual como B; por ejemplo, si muestra $2,000.00, ése es el valor de referencia, no un saldo que debas capturar. 3. Confirma que la cuenta está activa y corresponde al plantel y moneda de la operación; conserva su código y nombre para seleccionarla en el pago. 4. No edites saldo inicial ni registres movimientos manuales: sólo validar el pago de este caso debe aumentar el banco en $100.00.$texto$,$texto$Banco B antes de recibir el abono.$texto$,$texto$Referencia financiera anotada.$texto$,$texto$Aísla movimientos de otros usuarios; si hubo otras operaciones, compara también el movimiento del pago específico.$texto$,$texto$/admin/catalogos/cuentas-financieras$texto$),
('condonacion-abono-previo-100-400',3,$texto$Capturar el abono con tarjeta de $100$texto$,$texto$Administración$texto$,$texto$Pagos recibidos → Nuevo registro$texto$,$texto$1. Desde el menú lateral entra a Administración → Finanzas → Pagos recibidos → Nuevo registro. En Origen y responsable selecciona institución, plantel y tutor del alumno de la prueba. 2. En Adeudos que se van a pagar pulsa Agregar cargo, haz clic en Matrícula, alumno o concepto y selecciona el original de $500.00; la ayuda abre las primeras diez opciones y busca desde tres caracteres. Pulsa Registrar pago parcial y captura $100.00 en Importe que se aplicará. 3. En Datos del pago selecciona Tarjeta, la cuenta bancaria anotada, fecha y hora reales y la autorización o referencia disponible; para un registro controlado puedes usar TEST-ABONO-CONDONACION. Total recibido debe calcularse en $100.00. No actives la alternativa de dinero sin asignar; adjunta un comprobante de prueba si corresponde y captura una observación que identifique el ejercicio. 4. En Revisa y registra verifica saldo actual $500.00, importe de este pago $100.00 y Quedará por pagar $400.00. Pulsa Registrar como pendiente; revisa el modal y pulsa Confirmar y registrar como pendiente una sola vez.$texto$,$texto$Total recibido $100.00, distribuido $100.00, dinero pendiente de asignar $0.00; deuda restante estimada $400.00.$texto$,$texto$Pago pendiente, sin afectar todavía banco ni adeudo.$texto$,$texto$Dinero pendiente de asignar no significa deuda pendiente: $0.00 es correcto porque los $100.00 recibidos están asignados al cargo. Cancelar en el modal conserva captura y no guarda.$texto$,$texto$/admin/pagos/nuevo$texto$),
('condonacion-abono-previo-100-400',4,$texto$Validar y publicar el pago parcial$texto$,$texto$Administración$texto$,$texto$Pagos recibidos → Gestión$texto$,$texto$1. Desde el menú lateral entra a Administración → Finanzas → Pagos recibidos. Busca el pago de $100.00 por tutor o referencia, aplica filtros y pulsa Ver; anota su folio automático y confirma que es el recién registrado. 2. Abre Gestión → Control administrativo del pago; confirma método Tarjeta y cuenta destino bancaria precargada. No cambies la cuenta para este ejercicio. 3. Pulsa Validar y publicar; revisa importe $100.00 y cuenta en el modal. Puedes pulsar Cancelar para volver sin validar y conservar la captura. 4. Pulsa nuevamente Validar y publicar si cerraste el modal y confirma la operación una sola vez. Espera el estado Validado y consulta el comprobante oficial en otra pestaña.$texto$,$texto$Pago $100.00 validado, no un segundo pago de $500.00.$texto$,$texto$Abono aplicado y banco aumentado $100.00.$texto$,$texto$Guardar pendiente no equivale a validar. No crear un movimiento manual adicional: duplicaría el ingreso bancario.$texto$,$texto$/admin/catalogos/pagos$texto$),
('condonacion-abono-previo-100-400',5,$texto$Comprobar el abono antes de condonar$texto$,$texto$Administración y tutor$texto$,$texto$Adeudos, cuentas y portal familiar$texto$,$texto$1. Desde el menú lateral entra a Operación escolar → Cobranza escolar → Adeudos de alumnos; busca matrícula → Con saldo pendiente → Aplicar filtros → Ver del original. Confirma total $500.00, pagado acumulado $100.00 y saldo por pagar $400.00. 2. Entra a Administración → Finanzas → Cuentas financieras; busca la cuenta bancaria → Aplicar filtros y confirma Saldo actual B + $100.00. 3. En una ventana privada separada entra a /familias, inicia sesión con el tutor, selecciona el hijo → Tus pagos; confirma $400.00 pendientes y en el historial el pago de $100.00 con su comprobante. 4. Regresa a la ventana administrativa y conserva números de cargo, pago y cuenta; no liquides los $400.00 ni apliques descuento manual porque el siguiente paso usa convenio.$texto$,$texto$Total $500.00 = pagado $100.00 + pendiente $400.00.$texto$,$texto$Abono y comprobante conservados; saldo restante identificado.$texto$,$texto$Si no coinciden los importes, detenerse y revisar este pago; no corregir la diferencia con movimientos o ajustes adicionales.$texto$,$texto$/admin/catalogos/cargos$texto$),
('condonacion-abono-previo-100-400',6,$texto$Condonar únicamente los $400 restantes$texto$,$texto$Administración$texto$,$texto$Convenios de pago → Nuevo convenio$texto$,$texto$1. Desde el menú lateral entra a Operación escolar → Cobranza escolar → Convenios de pago → Nuevo convenio. Selecciona institución, el mismo tutor responsable y Concepto de cobro del convenio; elige un concepto activo de prueba, por ejemplo Convenio de pago. 2. Busca sus adeudos pendientes y agrega únicamente el cargo original de $500.00: la selección debe incluir su saldo pendiente de $400.00, no el importe original completo. 3. En Tipo de convenio selecciona Condonación total del saldo pendiente; captura Fecha del acuerdo de hoy, Descripción que verá la familia: Condonación del saldo restante de prueba, y Motivo del acuerdo: Prueba: condonación de los $400 restantes después de un pago validado de $100. Comprueba saldo incluido $400.00, nuevo monto por pagar $0.00 y condonado $400.00. En Condiciones comunicadas a la familia escribe: Se conserva el pago previo de $100 y se condonan los $400 restantes. La fecha de efecto será la del acuerdo en esta modalidad; el monto queda protegido en cero. No agregues otros cargos. 4. Confirma la creación mediante el modal, revisa tutor, cargo, motivo y ausencia de movimientos financieros; acepta una sola vez. Anota el folio del convenio y espera Condonado totalmente.$texto$,$texto$Saldo incluido $400.00, por pagar $0.00, condonado $400.00.$texto$,$texto$Se condona sólo la deuda restante; el abono de $100.00 permanece.$texto$,$texto$No cancelar el pago ni devolver $100.00. La condonación total no crea un cargo de cero ni implica recibir dinero.$texto$,$texto$/admin/convenios-pago/nuevo$texto$),
('condonacion-abono-previo-100-400',7,$texto$Verificar deuda cero sin cambiar el banco$texto$,$texto$Administración y tutor$texto$,$texto$Convenios, pagos, cuentas y portal familiar$texto$,$texto$1. Desde el menú lateral entra a Operación escolar → Cobranza escolar → Convenios de pago; busca el folio → Aplicar filtros → Ver → Resumen y Adeudos. Confirma Condonado totalmente, saldo sustituido $400.00, por pagar $0.00 y condonado $400.00, sin nuevos cargos. 2. Entra a Administración → Finanzas → Pagos recibidos; busca el folio del abono → Aplicar filtros → Ver. Confirma que los $100.00 siguen Validados y el comprobante continúa disponible. 3. En la ventana privada familiar entra a /familias, selecciona el hijo → Tus pagos y recarga; los $400.00 ya no deben aparecer como pendientes, pero el historial conserva el pago de $100.00 y su comprobante. 4. Regresa a Administración → Finanzas → Cuentas financieras, busca el banco → Aplicar filtros y confirma B + $100.00: no debe variar al condonar.$texto$,$texto$Deuda exigible $0.00; abono $100.00; banco B + $100.00.$texto$,$texto$Condonación conservadora del pago y sin movimiento financiero, confirmada por el propietario.$texto$,$texto$El original incluido en convenio no se convierte en dinero pagado; no sumar los $400.00 condonados al ingreso del banco.$texto$,$texto$/admin/convenios-pago$texto$),
('condonacion-abono-previo-100-400',8,$texto$Cancelar el convenio y reactivar sólo $400$texto$,$texto$Administración$texto$,$texto$Convenios de pago → Gestión$texto$,$texto$1. Desde el menú lateral entra a Operación escolar → Cobranza escolar → Convenios de pago; busca el folio de esta condonación → Aplicar filtros → Ver → Gestión → Cancelar convenio. 2. Captura Motivo obligatorio: Prueba: reactivar los $400 condonados conservando el pago previo de $100. Pulsa Cancelar y reactivar adeudos. 3. Revisa el modal: debe reactivar el saldo pendiente original de $400.00, conservar el abono y no mover dinero. Pulsa Cancelar si quieres revisar sin ejecutar; conserva el motivo. 4. Pulsa nuevamente Cancelar y reactivar adeudos si cerraste el modal, revisa y pulsa Confirmar cancelación del convenio. Espera Cancelado con motivo registrado. Si el convenio ya está cancelado, no repitas: consulta el siguiente paso.$texto$,$texto$Se reactiva la deuda $400.00; el pago $100.00 no se cancela.$texto$,$texto$Convenio cancelado con trazabilidad.$texto$,$texto$No tocar Cancelar cargo al alumno ni cancelar el pago. Si el servidor detecta cambios en abonos o ajustes desde el convenio, revisar el historial y no eludir el bloqueo.$texto$,$texto$/admin/convenios-pago$texto$),
('condonacion-abono-previo-100-400',9,$texto$Cerrar el caso: deuda $400, pago $100 y banco sin cambios$texto$,$texto$Administración y tutor$texto$,$texto$Convenios, adeudos, pagos, cuentas y portal familiar$texto$,$texto$1. Desde el menú lateral entra a Operación escolar → Cobranza escolar → Convenios de pago; busca folio → Aplicar filtros → Ver. Comprueba Cancelado y motivo. Saldo sustituido $400.00, por pagar $0.00 y condonado $400.00 son importes históricos del acuerdo anulado: no representan una condonación vigente. 2. Entra a Operación escolar → Cobranza escolar → Adeudos de alumnos; busca matrícula → Con saldo pendiente → Aplicar filtros → Ver del mismo original. Comprueba pagado acumulado $100.00 y saldo por pagar $400.00. En Administración → Finanzas → Pagos recibidos busca el folio → Aplicar filtros → Ver y verifica Validado y comprobante de $100.00. 3. En la ventana privada entra a /familias, selecciona el hijo → Tus pagos y recarga: deben reaparecer $400.00 pendientes y conservarse el registro pagado de $100.00 con comprobante. Vuelve a Administración → Finanzas → Cuentas financieras, busca banco → Aplicar filtros y verifica B + $100.00, sin cambios por crear o cancelar el convenio. 4. Para conservar evidencia entra a Operación escolar → Cobranza escolar → Convenios de pago; busca folio, filtra Cancelado → Aplicar filtros → Exportar Excel. Conserva los importes históricos y usa Adeudos para el saldo vigente. La prueba termina con $400.00 pendientes: no pagarlos otra vez ni borrar el historial como parte de este recorrido.$texto$,$texto$Original $500.00, abono $100.00, deuda vigente $400.00; banco B + $100.00.$texto$,$texto$El propietario confirmó la reaparición de $400.00, abono/comprobante de $100.00 y ausencia de cambios bancarios por condonar y cancelar.$texto$,$texto$Si el cargo ya venció puede mostrar Parcial · Vencido. La autorización para reportar cargos vencidos es independiente; no se habilita automáticamente al cancelar un convenio.$texto$,$texto$/admin/convenios-pago$texto$)
) v(slug,numero,titulo,perfil,modulo,instrucciones,ejemplo,resultado,precaucion,ruta) ON g.slug=v.slug;

-- Actualizar la referencia editorial pendiente sin modificar V83 aplicada.
UPDATE guia_proceso_paso SET precaucion=$texto$El ejemplo sin abonos tiene su propio alcance. El caso con abono previo también quedó confirmado y tiene otra guía: Condonar y reactivar $400 conservando un pago previo de $100; consultar ese recorrido para no duplicar operaciones.$texto$
WHERE guia_id=(SELECT id FROM guia_proceso WHERE slug='cancelar-condonacion-total-500') AND numero=7;
UPDATE guia_proceso SET version_contenido=version_contenido+1,revisada_el=DATE '2026-10-08'
WHERE slug='cancelar-condonacion-total-500';
